const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    // Western Brazil (approx.): long [-75,-56], lat [-15,5]
    const region = ee.Geometry.Polygon([
      [[-75, -15], [-75, 5], [-56, 5], [-56, -15], [-75, -15]]
    ], null, false);
    const startYear = 2002;
    const endYear = 2018;
    const years = ee.List.sequence(startYear, endYear);
    const band = 'Aerosol_Optical_Depth_Land_Ocean_Mean_Mean';

    // 2. Data Acquisition (Terra + Aqua monthly, August only)
    const terra = ee.ImageCollection('MODIS/061/MOD08_M3')
      .filter(ee.Filter.calendarRange(8, 8, 'month'))
      .filterDate(ee.Date.fromYMD(startYear, 1, 1), ee.Date.fromYMD(endYear + 1, 1, 1))
      .select([band]);
    const aqua = ee.ImageCollection('MODIS/061/MYD08_M3')
      .filter(ee.Filter.calendarRange(8, 8, 'month'))
      .filterDate(ee.Date.fromYMD(startYear, 1, 1), ee.Date.fromYMD(endYear + 1, 1, 1))
      .select([band]);

    const terraCount = await terra.size().getInfo();
    const aquaCount = await aqua.size().getInfo();

    if ((terraCount === 0) && (aquaCount === 0)) {
      console.log(`Collections: Terra=0, Aqua=0`);
      console.log(`No August data in ${startYear}-${endYear}.`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }

    // 3. Per-year combined (Terra + Aqua) stats for August
    const perYearFC = ee.FeatureCollection(years.map(function (y) {
      y = ee.Number(y);
      const start = ee.Date.fromYMD(y, 8, 1);
      const end = start.advance(1, 'month');
      const imgs = terra.filterDate(start, end).merge(aqua.filterDate(start, end));
      const n = imgs.size();
      const composite = ee.Image(ee.Algorithms.If(n.gt(0), imgs.mean(), null));
      const stats = ee.Dictionary(ee.Algorithms.If(
        n.gt(0),
        ee.Image(composite).reduceRegion({
          reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
          geometry: region,
          scale: 100000,
          maxPixels: 1e13
        }),
        ee.Dictionary({})
      ));
      const has = stats.contains(band + '_mean');
      const aod = ee.Number(ee.Algorithms.If(has, stats.get(band + '_mean'), null));
      const px = ee.Number(ee.Algorithms.If(has, stats.get(band + '_count'), 0));
      return ee.Feature(null, {
        year: y,
        imgCount: n,
        aod: aod,
        px: px
      });
    }));

    const totalImgs = await perYearFC.aggregate_sum('imgCount').getInfo();
    const totalValidPx = await perYearFC.aggregate_sum('px').getInfo();
    const yearsWithData = await perYearFC.filter(ee.Filter.notNull(['aod'])).size().getInfo();

    if (totalImgs === 0) {
      console.log(`Collections: Terra=${terraCount}, Aqua=${aquaCount}`);
      console.log(`No August images across ${startYear}-${endYear}.`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    if (totalValidPx === 0) {
      console.log(`Collections: Terra=${terraCount}, Aqua=${aquaCount}`);
      console.log(`Images exist but no valid pixels over region after processing.`);
      console.log('C2: No Valid Pixels (Images exist, but after cloud masking/processing, 0 pixels remain).');
      console.log('C2');
      return;
    }

    // 4. Regression (year vs AOD); also extract 2002 and 2018
    const validFC = perYearFC.filter(ee.Filter.notNull(['aod']));
    const lin = validFC.reduceColumns({
      reducers: ee.Reducer.linearFit(),
      selectors: ['year', 'aod']
    });
    const slope = await lin.get('scale').getInfo();
    const r2 = await lin.get('rSquared').getInfo();

    const f2002 = ee.Feature(perYearFC.filter(ee.Filter.eq('year', startYear)).first());
    const f2018 = ee.Feature(perYearFC.filter(ee.Filter.eq('year', endYear)).first());
    const aod2002 = await f2002.get('aod').getInfo();
    const px2002 = await f2002.get('px').getInfo();
    const aod2018 = await f2018.get('aod').getInfo();
    const px2018 = await f2018.get('px').getInfo();

    // 5. Validation & Final Answer
    const diff = (aod2018 != null && aod2002 != null) ? (aod2018 - aod2002) : null;
    const slopeNum = (slope !== null && slope !== undefined) ? Number(slope) : null;

    if (slopeNum === null || Number.isNaN(slopeNum)) {
      console.log(`Collections: Terra=${terraCount}, Aqua=${aquaCount}, Years used: ${yearsWithData}/17`);
      console.log(`Total valid px: ${totalValidPx}`);
      console.log(`2002 AOD: ${aod2002 !== null ? aod2002.toFixed(3) : 'null'} (px:${px2002})`);
      console.log(`2018 AOD: ${aod2018 !== null ? aod2018.toFixed(3) : 'null'} (px:${px2018})`);
      console.log(`Trend slope/yr: null, r2: ${r2 !== null ? r2.toFixed(3) : 'null'}`);
      console.log('C3: Calculation Failure (Result is None, NaN, or invalid).');
      console.log('C3');
      return;
    }

    const decrease = (slopeNum < 0) && (diff === null || diff < 0);

    // Evidence (<=20 lines total)
    console.log(`Collections: Terra=${terraCount}, Aqua=${aquaCount}, Years used: ${yearsWithData}/17`);
    console.log(`Total images combined: ${totalImgs}, Total valid px: ${totalValidPx}`);
    console.log(`2002 AOD: ${aod2002 !== null ? aod2002.toFixed(3) : 'null'} (px:${px2002})`);
    console.log(`2018 AOD: ${aod2018 !== null ? aod2018.toFixed(3) : 'null'} (px:${px2018})`);
    console.log(`Trend slope/yr: ${slopeNum.toFixed(5)}, r2: ${r2 !== null ? r2.toFixed(3) : 'null'}`);
    console.log(`Δ(2018-2002): ${diff !== null ? diff.toFixed(3) : 'null'}`);

    if (decrease) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('Error:', err && err.message ? err.message : String(err));
    console.log('D: If image, collection, or band names are incorrect, syntax or method error, wrong method, or memory issue, etc.');
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
